let magnifier=null;
const toggle=document.querySelector('.menu-toggle');
const menu=document.querySelector('#mobile-nav');
function setMenu(open){menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('span').textContent=open?ui[activeLanguage].close:ui[activeLanguage].menu;document.body.classList.toggle('menu-open',open);}
toggle.addEventListener('click',()=>setMenu(toggle.getAttribute('aria-expanded')!=='true'));
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){setMenu(false);toggle.focus();}if(e.key==='Tab'&&!menu.hidden){const items=[toggle,...menu.querySelectorAll('a')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
const mobile=matchMedia('(max-width:760px)');mobile.addEventListener('change',()=>{if(!mobile.matches)setMenu(false);});
const motion=matchMedia('(prefers-reduced-motion:reduce)');
if(!motion.matches&&'IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}}),{threshold:.07});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('will-reveal');io.observe(el);});}
const buttons=[...document.querySelectorAll('.world-button')];
buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(b=>{const active=b===button;b.classList.toggle('is-active',active);b.setAttribute('aria-expanded',String(active));document.getElementById(b.getAttribute('aria-controls')).hidden=!active;});}));
const hero=document.querySelector('.hero');const picture=document.querySelector('.hero-picture');const progress=document.querySelector('.reading-progress');let scheduled=false;
function updateScroll(){scheduled=false;const y=window.scrollY;const total=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${total?Math.min(1,y/total):0})`;picture.style.setProperty('--hero-scroll',!motion.matches&&y<hero.offsetHeight&&innerWidth>760?`${y*.17}px`:'0px');}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateScroll);}},{passive:true});addEventListener('resize',updateScroll);updateScroll();

if(!motion.matches&&matchMedia('(pointer:fine)').matches){addEventListener('pointermove',e=>{document.documentElement.style.setProperty('--cursor-light-x',`${e.clientX}px`);document.documentElement.style.setProperty('--cursor-light-y',`${e.clientY}px`);},{passive:true});const setHeroDepth=e=>{const box=hero.getBoundingClientRect();const x=(e.clientX-box.left)/box.width-.5;const y=(e.clientY-box.top)/box.height-.5;hero.style.setProperty('--hero-x',`${x*-12}px`);hero.style.setProperty('--hero-y',`${y*-9}px`);hero.style.setProperty('--hero-scale','1.045');hero.classList.add('is-tilting')};hero.addEventListener('pointermove',setHeroDepth,{passive:true});hero.addEventListener('pointerleave',()=>{hero.style.removeProperty('--hero-x');hero.style.removeProperty('--hero-y');hero.style.removeProperty('--hero-scale');hero.classList.remove('is-tilting')});}

const headerLanguages=document.querySelector('.header-actions .language-switcher');if(headerLanguages){const mobileLanguages=headerLanguages.cloneNode(true);mobileLanguages.classList.add('mobile-language');menu.append(mobileLanguages);}
